type Path=string & {__pathBrand:void;};
function isRootedDiskPath(path:string):boolean {return path.startsWith('/');}
function normalizePath(path:string):string {return path;}
function getNormalizedAbsolutePath(path:string,base:string|undefined):string {return (base ?? '')+'/'+path;}
export function toPath(fileName: string, basePath: string | undefined, getCanonicalFileName: (path: string) => string): Path {
    const nonCanonicalizedPath = isRootedDiskPath(fileName)
        ? normalizePath(fileName)
        : getNormalizedAbsolutePath(fileName, basePath);
    return getCanonicalFileName(nonCanonicalizedPath) as Path;
}
